import { test, expect } from '@playwright/test';

test.describe('Add and Delete Elements - Element Manager', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/add_remove_elements');
  });

  test('should add two elements and delete one, leaving one added-manually button on the page', async ({ page }) => {
    // Verify initial state
    const initialCount = page.locator('[data-testid="element-count"]').count();
    expect(initialCount).toBe(0);

    // Add first element
    const addButton = page.getByRole('button', { name: /add element/i });
    await addButton.click();

    // Verify first delete button appears
    const firstDeleteButton = page.getByRole('button', { name: /delete/i });
    await expect(firstDeleteButton).toBeVisible();

    // Add second element
    await addButton.click();

    // Verify second delete button appears
    const secondDeleteButton = page.getByRole('button', { name: /delete/i });
    await expect(secondDeleteButton).toBeVisible();

    // Verify element count is now 2
    const updatedCount = page.locator('[data-testid="element-count"]').count();
    expect(updatedCount).toBe(2);

    // Click first delete button
    await firstDeleteButton.click();

    // Verify only one added-manually button remains
    const remainingDeleteButton = page.getByRole('button', { name: /delete/i });
    await expect(remainingDeleteButton).toBeVisible();

    // Verify element count is now 1
    const finalCount = page.locator('[data-testid="element-count"]').count();
    expect(finalCount).toBe(1);
  });

  test('should handle adding and deleting multiple elements with error handling', async ({ page }) => {
    // Verify initial state
    const initialCount = page.locator('[data-testid="element-count"]').count();
    expect(initialCount).toBe(0);

    // Add multiple elements
    const addButton = page.getByRole('button', { name: /add element/i });
    await addButton.click();
    await addButton.click();
    await addButton.click();

    // Verify element count is now 3
    const updatedCount = page.locator('[data-testid="element-count"]').count();
    expect(updatedCount).toBe(3);

    // Verify all delete buttons are visible
    const deleteButtons = page.locator('[data-testid="delete-button"]');
    await expect(deleteButtons).toHaveCount(3);

    // Click first delete button
    const firstDeleteButton = page.getByRole('button', { name: /delete/i });
    await firstDeleteButton.click();

    // Verify second delete button is now visible
    const secondDeleteButton = page.getByRole('button', { name: /delete/i });
    await expect(secondDeleteButton).toBeVisible();

    // Click second delete button
    await secondDeleteButton.click();

    // Verify only one delete button remains
    const remainingDeleteButton = page.getByRole('button', { name: /delete/i });
    await expect(remainingDeleteButton).toBeVisible();

    // Verify element count is now 2
    const finalCount = page.locator('[data-testid="element-count"]').count();
    expect(finalCount).toBe(2);

    // Verify error message is displayed when clicking delete button on empty list
    const errorMessage = page.getByText(/no elements to delete/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message disappears after adding a new element
    await addButton.click();
    await expect(errorMessage).not.toBeVisible();
  });
});
